<template><div class="app-container"><div class="page-header"><div><h1>Flow Preview</h1><p>Run the same purchase, access and Credits APIs used by the App samples.</p></div><div class="page-actions"><el-button @click="load">Refresh</el-button><el-button @click="$router.push({path:'/app/home',query:{user:userId}})">Open App</el-button></div></div><el-alert title="Demo controls. These actions update the local prototype database. No real payment, store subscription or LLM request is made." type="warning" :closable="false" class="module-notice"/><el-form inline><el-form-item label="Scenario User"><el-select v-model="userId" @change="clearAndLoad"><el-option v-for="u in users" :key="u.id" :value="u.id" :label="u.name+' · '+u.scenario"/></el-select></el-form-item></el-form><template v-if="data"><div class="user-summary"><span>{{ data.effective.base.name }}</span><span v-for="account in data.wallet.accounts.filter(account=>!account.future&&(account.code!=='LEGACY_CREDIT'||data.wallet.batches.some(batch=>batch.creditType===account.code)))" :key="account.code">{{ account.available }} {{ account.name }} available / {{ account.reserved }} reserved</span><span>{{ data.assets.length }} saved assets</span></div><subscription-demo :subscriptions="data.subscriptions" @changed="load"/><div class="operations-grid"><section class="section-card"><h2 class="section-title">1 · Purchase</h2><div class="section-body"><p>Membership creates a Base period and scheduled gifts. Credits top-ups create an independent batch.</p><el-button type="primary" @click="purchaseVisible=true">Purchase Preview</el-button><el-button @click="$router.push('/commercialization/orders')">View Orders</el-button></div></section><section class="section-card"><h2 class="section-title">2 · Feature Access &amp; Credits</h2><div class="section-body"><el-select v-model="serviceId" style="width:100%" @change="serviceQuote=null;decision=null"><el-option v-for="s in data.services" :key="s.id" :value="s.id" :label="s.name+' · '+serviceBilling(s)"/></el-select><el-input v-model="message" type="textarea" placeholder="Your AI question (required for User Turns)" maxlength="5000" style="margin:12px 0"/><div class="action-row"><el-button :loading="busy" @click="reviewService">Check / Quote</el-button><el-button v-if="serviceQuote && !request" type="primary" :loading="busy" @click="start">Confirm &amp; Reserve</el-button></div><el-alert v-if="decision" :type="decision.allowed?'success':'warning'" :title="decision.reason+' · '+decision.message" :closable="false"/><p v-if="serviceQuote">Source: {{ serviceQuote.billingSource }} · {{ serviceQuote.billingSource==='feature'?'No Credits used':serviceQuote.credits+' '+creditTypeLabel(serviceQuote.creditType||'LEGACY_CREDIT') }} · v{{ serviceQuote.priceVersion }} · expires {{ dateTime(serviceQuote.expiresAt) }}</p><div v-if="request"><p>Status: <strong>{{ request.status }}</strong> · {{ request.credits }} Credits</p><div v-if="request.status==='reserved'" class="action-row"><el-button type="success" :loading="busy" @click="finish('succeeded')">Complete &amp; Settle</el-button><el-button :loading="busy" @click="finish('failed')">Fail &amp; Release</el-button></div><p v-else class="field-help">Terminal state. Repeated callbacks keep this result and do not charge again.</p></div></div></section><section class="section-card"><h2 class="section-title">3 · Content Access / Redemption</h2><div class="section-body"><el-select v-model="contentId" style="width:100%" @change="contentDecision=null;redemptionQuote=null;redemptionResult=null"><el-option v-for="c in data.contents" :key="c.id" :value="c.id" :label="c.name+' · '+c.contentType+' · '+c.tier"/></el-select><div class="action-row"><el-button :loading="busy" @click="checkContent">Check Start / Select / Join</el-button><el-button v-if="contentDecision && contentDecision.reason==='REDEMPTION_REQUIRED'" :loading="busy" @click="reviewRedemption">Review Redemption</el-button></div><el-alert v-if="contentDecision" :title="contentDecision.reason+' · '+contentDecision.message" :type="contentDecision.allowed?'success':'warning'" :closable="false"/><div v-if="redemptionQuote" class="quote-card"><p>{{ redemptionQuote.name }} · {{ redemptionQuote.credits }} Credits · {{ redemptionQuote.validityDays?redemptionQuote.validityDays+' days':'No expiry' }}</p><el-button type="primary" :loading="busy" @click="confirmRedemption">Confirm Redemption</el-button></div><el-alert v-if="redemptionResult" :title="redemptionResult" type="success" :closable="false"/></div></section><section class="section-card"><h2 class="section-title">4 · Expiry / Existing Assets</h2><div class="section-body"><p>Simulate expiry, then reopen the App or inspect the user’s rights and assets.</p><div class="action-row"><el-button :disabled="!data.effective.membershipActive || busy" @click="expire()">Expire Current Membership</el-button><el-button @click="$router.push({path:'/commercialization/users/'+userId,query:{tab:'assets'}})">Read Saved Assets</el-button></div><el-select v-model="batchId" clearable placeholder="Choose an available Credits batch" style="width:100%"><el-option v-for="b in data.wallet.batches.filter(b=>b.available>0 && !b.reserved && !b.neverExpires)" :key="b.id" :value="b.id" :label="b.source+' · '+b.available+' Credits · '+dateTime(b.expiresAt)"/></el-select><el-button :disabled="!batchId || busy" style="margin-top:12px" @click="expire(batchId)">Expire Selected Batch</el-button><p class="field-help">Expiry controls are for review only. Credits and membership are independent; saved assets remain readable.</p></div></section></div></template><el-alert v-if="error" :title="error" type="error" :closable="false"/><purchase-dialog :visible.sync="purchaseVisible" :user-id="userId" @changed="load"/></div></template>
<script>
import {listUsers,getStorefront,quoteService,startService,finishService,access,quoteRedemption,redeem,demoExpire,requestKey} from '@/api/commerce'
import {creditTypeLabel} from '@/utils/entitlements'
import {dateTime} from '@/utils/format'
import PurchaseDialog from '@/components/Commerce/PurchaseDialog'
import SubscriptionDemo from '@/components/Commerce/SubscriptionDemo'
export default{components:{PurchaseDialog,SubscriptionDemo},data(){return{users:[],userId:this.$route.query.user||'DEMO-2002',data:null,serviceId:'ai_chat',contentId:'course_featured',message:'',decision:null,serviceQuote:null,request:null,contentDecision:null,redemptionQuote:null,redemptionResult:null,key:'',redeemKey:'',batchId:'',purchaseVisible:false,busy:false,error:''}},async created(){this.users=await listUsers();this.load()},methods:{dateTime,creditTypeLabel,serviceBilling(service){return service.billingModel==='feature'?'Feature access / No Credits':service.credits===null?'Amount not configured':service.credits+' '+creditTypeLabel(service.creditType||'LEGACY_CREDIT')+(service.unit==='user_turn'?' / User Turn':'')},async load(){try{this.data=await getStorefront(this.userId);if(!this.data.services.some(row=>row.id===this.serviceId))this.serviceId=this.data.services[0]?.id;if(!this.data.contents.some(row=>row.id===this.contentId))this.contentId=this.data.contents[0]?.id}catch(e){this.error=e.message}},clearAndLoad(){this.decision=null;this.serviceQuote=null;this.request=null;this.contentDecision=null;this.redemptionQuote=null;this.redemptionResult=null;this.batchId='';this.load()},async task(work){this.busy=true;this.error='';try{await work()}catch(e){this.error=e.message}finally{this.busy=false}},async reviewService(){this.request=null;this.task(async()=>{const result=await quoteService({userId:this.userId,serviceId:this.serviceId});this.decision=result.decision;this.serviceQuote=result.quote;this.key=requestKey()})},async start(){this.task(async()=>{this.request=await startService({userId:this.userId,quoteId:this.serviceQuote.id,message:this.message,requestKey:this.key,acceptOverage:this.serviceQuote.requiresOverageConsent===true});await this.load()})},async finish(outcome){this.task(async()=>{this.request=await finishService(this.request.id,outcome);await this.load()})},async checkContent(){this.task(async()=>{this.contentDecision=await access({userId:this.userId,contentId:this.contentId})})},async reviewRedemption(){this.task(async()=>{const result=await quoteRedemption({userId:this.userId,contentId:this.contentId});if(result.alreadyRedeemed)this.redemptionResult='Already redeemed · no charge';else if(!result.quote)this.error=`Needs ${result.credits} Credits; ${result.available} available.`;else{this.redemptionQuote=result.quote;this.redeemKey=requestKey()}})},async confirmRedemption(){this.task(async()=>{const result=await redeem({userId:this.userId,quoteId:this.redemptionQuote.id,requestKey:this.redeemKey});this.redemptionResult='Redeemed · '+dateTime(result.expiresAt);this.redemptionQuote=null;await this.load();this.contentDecision=await access({userId:this.userId,contentId:this.contentId})})},async expire(batchId){try{await this.$confirm('Apply this simulated expiry to the local demo data? Saved assets remain.','Simulate Expiry',{confirmButtonText:'Expire',type:'warning'})}catch(_){return}this.task(async()=>{await demoExpire({userId:this.userId,batchId});this.batchId='';await this.load()})}}}
</script>
